def apply(inputs,premises):
    task=inputs.get('task_id')
    entries=root_entries(premises)
    if task=='Knowledge Definition-Answer':
        specified=roots_with(entries,'knowledge_definition_rule','reasonable_inquiry_of')
        unspecified=roots_with(entries,'knowledge_definition_rule','reasonable_inquiry_with_unspecified_target')
        inquiry=unique_ids(specified+unspecified)
        actual_only=roots_with(entries,'knowledge_definition_rule','actual_knowledge_only')
        if inquiry and not actual_only:
            return {'handled':True,'answer':'Constructive knowledge','used_nodes':inquiry}
        if actual_only and not inquiry:
            return {'handled':True,'answer':'Actual knowledge','used_nodes':actual_only}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if task=='Ordinary Course Covenant includes carve-out for Pandemic responses-Answer (Y/N)':
        yes=[]
        no=[]
        for root,term in entries:
            if term_has(term,'ordinary_course_operations') and term_has(term,'pandemic_exception_applies_to'):
                yes.append(root)
            if term_has(term,'ordinary_course_operations') and term_has(term,'complete_source_no_pandemic_exception_for'):
                no.append(root)
        yes=unique_ids(yes)
        no=unique_ids(no)
        if yes and not no:
            return {'handled':True,'answer':'Yes','used_nodes':yes}
        if no and not yes:
            return {'handled':True,'answer':'No','used_nodes':no}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if task=='Negative Interim Covenant includes carveout for pandemic responses-Answer (Y/N)':
        yes=[]
        no=[]
        for root,term in entries:
            if term_has(term,'negative_interim_restrictions') and term_has(term,'pandemic_exception_applies_to'):
                yes.append(root)
            if term_has(term,'negative_interim_restrictions') and term_has(term,'complete_source_no_pandemic_exception_for'):
                no.append(root)
        yes=unique_ids(yes)
        no=unique_ids(no)
        if yes and not no:
            return {'handled':True,'answer':'Yes','used_nodes':yes}
        if no and not yes:
            return {'handled':True,'answer':'No','used_nodes':no}
        return {'handled':False,'answer':None,'used_nodes':[]}
    return {'handled':False,'answer':None,'used_nodes':[]}
